-- Generated by pwc-to-dbt from PowerCenter mapping m_FL_JS_MARTS_CORE: target CUSTOMERS (instance CUSTOMERS).
-- Do not edit by hand; change the mapping or the converter and regenerate.
-- Flow: SQ_STG_CUSTOMERS -> SQ_STG_ORDERS2 -> AGG_ORDERS_BY_CUSTOMER -> JNR_CUSTOMERS_ORDERS -> EXP_CUSTOMER_METRICS -> CUSTOMERS

with

sq_stg_customers as (
    -- SQ_STG_CUSTOMERS (Source Qualifier): reads STG_CUSTOMERS
    select
        cast(customer_id as varchar) as customer_id,
        cast(customer_name as varchar) as customer_name
    from {{ ref('stg_customers') }}
),

sq_stg_orders2 as (
    -- SQ_STG_ORDERS2 (Source Qualifier): reads STG_ORDERS
    select
        cast(order_id as varchar) as order_id,
        cast(customer_id as varchar) as customer_id,
        cast(location_id as varchar) as location_id,
        cast(ordered_at_day as timestamp) as ordered_at_day,
        cast(subtotal_cents as double) as subtotal_cents,
        cast(tax_paid_cents as double) as tax_paid_cents,
        cast(order_total_cents as decimal(12, 2)) as order_total_cents,
        cast(subtotal as double) as subtotal,
        cast(tax_paid as double) as tax_paid,
        cast(order_total as decimal(12, 2)) as order_total
    from {{ ref('stg_orders') }}
),

agg_orders_by_customer as (
    -- AGG_ORDERS_BY_CUSTOMER (Aggregator) grouped by CUSTOMER_ID
    select
        customer_id as customer_id,
        count(order_id) as lifetime_orders,
        min(ordered_at_day) as first_order_date,
        max(ordered_at_day) as last_order_date,
        sum(order_total) as lifetime_spend,
        sum(subtotal) as lifetime_spend_pretax,
        sum(tax_paid) as lifetime_tax_paid
    from sq_stg_orders2
    group by customer_id
),

jnr_customers_orders as (
    -- JNR_CUSTOMERS_ORDERS (Joiner, Master Outer Join): CUSTOMER_ID = CUSTOMER_ID1
    select
        master.customer_id as customer_id,
        master.customer_name as customer_name,
        detail.lifetime_orders as lifetime_orders,
        detail.first_order_date as first_order_date,
        detail.last_order_date as last_order_date,
        detail.lifetime_spend as lifetime_spend,
        detail.lifetime_spend_pretax as lifetime_spend_pretax,
        detail.lifetime_tax_paid as lifetime_tax_paid
    from agg_orders_by_customer as detail
    left join sq_stg_customers as master
        on (master.customer_id = detail.customer_id)
),

exp_customer_metrics as (
    -- EXP_CUSTOMER_METRICS (Expression)
    select
        customer_id as customer_id,
        customer_name as customer_name,
        case when (lifetime_orders is null) then 0 else lifetime_orders end as lifetime_orders_cl,
        first_order_date as first_order_date,
        last_order_date as last_order_date,
        case when (lifetime_spend is null) then 0 else lifetime_spend end as lifetime_spend_cl,
        case when (lifetime_spend_pretax is null) then 0 else lifetime_spend_pretax end as lifetime_spend_pretax_cl,
        case when (lifetime_tax_paid is null) then 0 else lifetime_tax_paid end as lifetime_tax_paid_cl,
        case when (case when (lifetime_orders is null) then 0 else lifetime_orders end > 1) then 'returning' else 'new' end as customer_type
    from jnr_customers_orders
),

final as (
    -- CUSTOMERS (Target CUSTOMERS): cast to the target column types
    select
        cast(customer_id as varchar) as customer_id,
        cast(customer_name as varchar) as customer_name,
        cast(lifetime_orders_cl as decimal(15, 0)) as lifetime_orders,
        cast(first_order_date as timestamp) as first_order_date,
        cast(last_order_date as timestamp) as last_order_date,
        cast(lifetime_spend_cl as decimal(12, 2)) as lifetime_spend,
        cast(lifetime_spend_pretax_cl as decimal(12, 2)) as lifetime_spend_pretax,
        cast(lifetime_tax_paid_cl as decimal(12, 2)) as lifetime_tax_paid,
        cast(customer_type as varchar) as customer_type
    from exp_customer_metrics
)

select * from final
